memo-context — Memoize Context
Problem: color and name live in App inside one FooterContext,
and the value is an inline { color, name }. Clicking the unrelated app
counter re-renders every component, including the memoized Footer.
function App() {
	const [appCount, setAppCount] = useState(0)
	const [color, setColor] = useState(&#039;black&#039;)
	const [name, setName] = useState(&#039;&#039;)
	const value = useMemo(() =&gt; ({ color, name }), [color, name])
	return (
		&lt;FooterContext value={value}&gt;
			&lt;div&gt;
				&lt;FooterSetters setName={setName} setColor={setColor} /&gt;
				&lt;button onClick={() =&gt; setAppCount((c) =&gt; c + 1)}&gt;
					The app count is {appCount}
				&lt;/button&gt;
				&lt;Main footer={&lt;Footer /&gt;} /&gt;
			&lt;/div&gt;
		&lt;/FooterContext&gt;
	)
}
